[CmdletBinding()]
param(
  [Parameter(Mandatory = $true)][string]$In,
  [string]$Out = ".\assets\frames",
  [int]$Width = 900,
  [int]$Height = 1125,
  [int]$PerClip = 7,
  [double]$HeadCut = 0.06,
  [double]$TailCut = 0.06,
  [string]$Ffmpeg = "ffmpeg",
  [string]$Ffprobe = ""
)

# Turn A->B transition clips (generated by an image-to-video model with
# first/last frame) into an evenly spaced frame sequence: frame-00.jpg ...
# Feed the result to index.html's frame-sequence mode.
# Keep this file pure ASCII: Windows PowerShell mangles CJK literals in .ps1.

$ErrorActionPreference = "Stop"

if (-not (Test-Path -LiteralPath $In)) { throw "Input folder not found: $In" }
if (-not (Test-Path -LiteralPath $Out)) { New-Item -ItemType Directory -Force -Path $Out | Out-Null }
$OutFull = (Resolve-Path -LiteralPath $Out).Path

if (-not $Ffprobe) {
  $probeGuess = Join-Path (Split-Path -Parent $Ffmpeg) "ffprobe.exe"
  if (Test-Path -LiteralPath $probeGuess) { $Ffprobe = $probeGuess } else { $Ffprobe = "ffprobe" }
}

function Get-DurationSeconds($file) {
  $d = $null
  try {
    $raw = & $Ffprobe -v error -show_entries format=duration -of default=nw=1:nk=1 $file 2>$null
    $d = [double]::Parse(($raw | Select-Object -First 1).ToString(), [Globalization.CultureInfo]::InvariantCulture)
  } catch {
    $txt = (& $Ffmpeg -i $file 2>&1 | Out-String)
    $m = [regex]::Match($txt, "Duration:\s*(\d+):(\d+):(\d+\.?\d*)")
    if ($m.Success) {
      $d = [double]$m.Groups[1].Value * 3600 + [double]$m.Groups[2].Value * 60 + [double]::Parse($m.Groups[3].Value, [Globalization.CultureInfo]::InvariantCulture)
    }
  }
  return $d
}

$clips = @(Get-ChildItem -LiteralPath $In -File | Where-Object { $_.Extension -imatch '^\.(mp4|mov|webm|mkv)$' } | Sort-Object Name)
if ($clips.Count -eq 0) { throw "No video clips (mp4/mov/webm/mkv) found in $In" }

# 清掉上一轮产出的帧，避免新旧混在一起
Get-ChildItem -LiteralPath $OutFull -File -Filter "frame-*.jpg" | Remove-Item -Force -ErrorAction SilentlyContinue

$index = 0
$rows = New-Object System.Collections.ArrayList
$vf = "scale=$Width`:$Height`:force_original_aspect_ratio=increase,crop=$Width`:$Height"

foreach ($c in $clips) {
  $dur = Get-DurationSeconds $c.FullName
  if (-not $dur -or $dur -le 0.2) {
    [void]$rows.Add([pscustomobject]@{ Clip = $c.Name; Duration = "?"; Frames = 0; Status = "SKIP (no duration)" })
    continue
  }
  $t0 = $dur * $HeadCut
  $t1 = $dur * (1 - $TailCut)
  $span = $t1 - $t0
  $made = 0

  for ($i = 0; $i -lt $PerClip; $i++) {
    $t = $t0 + $span * (($i + 1) / ($PerClip + 1))
    $name = "frame-{0:d2}.jpg" -f $index
    $dst = Join-Path $OutFull $name
    & $Ffmpeg -loglevel error -y -ss ("{0:F3}" -f $t) -i $c.FullName -frames:v 1 -q:v 3 -vf $vf $dst 2>$null
    if (Test-Path -LiteralPath $dst) { $index++; $made++ }
  }

  [void]$rows.Add([pscustomobject]@{
    Clip     = $c.Name
    Duration = ("{0:N2}s" -f $dur)
    Frames   = $made
    Status   = "OK"
  })
}

$rows | Format-Table -AutoSize
Write-Host ""
Write-Host ("Done: {0} frames -> {1}" -f $index, $OutFull) -ForegroundColor Green
Write-Host ("Each frame {0} x {1}. Now index.html can run in frame-sequence mode." -f $Width, $Height)
